// Finds today's row in the sheet and normalises it for the payload builder.
// The Date column should be YYYY-MM-DD (see the sheet sticky note).
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json);
if (!rows.length) {
  throw new Error('The sheet returned no rows. Pick your spreadsheet + sheet in "Read workout sheet" and make sure it has a header row.');
}

function pickTodaysRow(cfg, rows, nowDate) {
  const tzOpt = cfg.timezone ? { timeZone: cfg.timezone } : {};
  const todayIso = (nowDate || new Date()).toLocaleDateString('en-CA', tzOpt);

  // Header lookup ignores case, spaces and underscores ("Workout Name" works).
  const getCol = (row, name) => {
    const want = name.toLowerCase();
    for (const k of Object.keys(row)) {
      if (String(k).toLowerCase().replace(/[\s_]/g, '') === want) return row[k];
    }
    return undefined;
  };

  // Accepts YYYY-MM-DD (recommended), anything Date.parse understands, and
  // Google Sheets date serials (days since 1899-12-30).
  const isoOf = (v) => {
    if (v == null || v === '') return null;
    if (typeof v === 'number' && v > 20000 && v < 80000) {
      return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 10);
    }
    const s = String(v).trim();
    const m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(s);
    if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
    const d = new Date(s);
    return Number.isNaN(d.getTime()) ? null : d.toLocaleDateString('en-CA');
  };

  const dated = rows
    .map((row) => ({ row, iso: isoOf(getCol(row, 'date')) }))
    .filter((x) => x.iso);
  if (!dated.length) {
    throw new Error('No row has a readable Date. Use YYYY-MM-DD in the Date column (format the column as plain text).');
  }

  let hit = dated.find((x) => x.iso === todayIso);
  if (!hit && cfg.fallbackToLatest) {
    hit = dated.filter((x) => x.iso <= todayIso).sort((a, b) => (a.iso < b.iso ? 1 : -1))[0];
  }
  if (!hit) {
    throw new Error(`No workout row for today (${todayIso}). Add a row with Date = ${todayIso}, or set fallbackToLatest: true in Config to reuse the latest past workout.`);
  }

  const row = hit.row;
  const workoutName = String(getCol(row, 'workoutname') ?? '').trim();
  if (!workoutName) throw new Error(`The row for ${hit.iso} has an empty WorkoutName.`);

  // Ex1..Ex5 hold "Exercise x Reps" — split on the LAST " x " so exercise
  // names containing " x " and reps like "5x5" both survive.
  const exercises = [];
  for (let i = 1; i <= 5; i += 1) {
    const cell = String(getCol(row, 'ex' + i) ?? '').trim();
    if (!cell) continue;
    const seps = [...cell.matchAll(/\s[x×]\s/gi)];
    let name = cell;
    let reps = '';
    if (seps.length) {
      const last = seps[seps.length - 1];
      name = cell.slice(0, last.index).trim();
      reps = cell.slice(last.index + last[0].length).trim();
    }
    if (name) exercises.push({ name, reps });
  }
  if (!exercises.length) {
    throw new Error(`The row for ${hit.iso} has no exercises. Fill Ex1..Ex5 as "Exercise x Reps", e.g. "Bench press x 5x5".`);
  }

  // "MON, JUL 27" — built from the sheet date, not the server clock, so a
  // fallbackToLatest row shows ITS date, never a wrong one.
  const [y, mo, d] = hit.iso.split('-').map(Number);
  const dateLabel = new Date(Date.UTC(y, mo - 1, d, 12))
    .toLocaleDateString(cfg.dateLocale || 'en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' })
    .toUpperCase();

  return {
    workoutName,
    focus: String(getCol(row, 'focus') ?? '').trim(),
    coachNote: String(getCol(row, 'coachnote') ?? '').trim(),
    dateLabel,
    dateIso: hit.iso,
    usedFallback: hit.iso !== todayIso,
    exercises,
  };
}

return [{ json: pickTodaysRow(cfg, rows, new Date()) }];

// Assembles the Zvid project JSON: hero-footage hook, the full workout
// board, and the coach's-note close. Adapted from the fitness-wod library
// example — layout constants and type tiers are explained inline.
const cfg = $('Config').first().json;
const data = $input.first().json;

function buildProject(config, data) {
  const escapeHtml = (s) =>
    String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const round = (n) => Math.round(n * 100) / 100;

  // SVG decorations need the accent at reduced opacity; accept #RGB / #RRGGBB
  // and fall back to the raw string (full opacity) for anything else.
  const accentAlpha = (alpha) => {
    const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(config.accent || '').trim());
    if (!m) return config.accent || '#C6FF3D';
    let h = m[1];
    if (h.length === 3) h = h.split('').map((c) => c + c).join('');
    const n = parseInt(h, 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${alpha})`;
  };

  const accent = config.accent || '#C6FF3D';
  const bg = config.background || '#07080A';
  const font = config.font || 'Archivo';
  const handle = String(config.handle || '').trim();
  const gymName = String(config.gymName || 'THE GYM').trim();

  const workoutName = String(data.workoutName || '').trim();
  if (!workoutName) throw new Error('workoutName is empty — check the WorkoutName column for today\'s row.');
  const focus = String(data.focus || '').trim();
  const dateLabel = String(data.dateLabel || '').trim();
  const coachNote = String(data.coachNote || '').trim() || 'Log your lifts. Tag the gym.';

  const exercises = (Array.isArray(data.exercises) ? data.exercises : [])
    .map((e) => ({ name: String(e && e.name || '').trim(), reps: String(e && e.reps || '').trim() }))
    .filter((e) => e.name)
    .slice(0, 5);
  if (!exercises.length) throw new Error('No exercises for today — fill at least the Ex1 column.');

  // ---- adaptive type sizes (fixed layout, so long strings scale down instead
  // of colliding with the next block) --------------------------------------
  const titleSize = workoutName.length <= 12 ? 118 : workoutName.length <= 24 ? 92 : 68;
  const boardTitleSize = workoutName.length <= 18 ? 58 : workoutName.length <= 30 ? 46 : 38;
  const longestName = Math.max(...exercises.map((e) => e.name.length));
  const nameSize = longestName <= 26 ? 46 : longestName <= 44 ? 40 : 34; // one size for every row
  const noteSize = coachNote.length <= 45 ? 64 : coachNote.length <= 100 ? 52 : 42;

  const HOOK_D = 3.8;
  const BOARD_D = 5.4;
  const COACH_D = 4.4;

  // The layout linter reads style.color (not the inline HTML), so every TEXT
  // declares its dominant on-screen colour there. Chip/pill elements declare
  // the accent — the chip itself is what carries the contrast on screen.
  const DIM = '#8C9196'; // muted labels — keeps >4.5:1 on the dark background
  const FOOT = '#85898D'; // footer lines

  // ---- scene 1: hook ------------------------------------------------------
  const hook = {
    id: 'hook',
    duration: HOOK_D,
    backgroundColor: bg,
    transition: 'smoothup',
    transitionId: 'board',
    transitionDuration: 0.55,
    visuals: [
      {
        type: 'VIDEO', src: config.heroVideo, width: 1080, height: 1920,
        position: 'center-center', resize: 'cover', volume: 0, track: 0,
        enterBegin: 0, exitEnd: HOOK_D,
      },
      {
        type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: HOOK_D,
        svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='wodHook' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='${bg}' stop-opacity='0.72'/><stop offset='0.42' stop-color='${bg}' stop-opacity='0.15'/><stop offset='1' stop-color='${bg}' stop-opacity='0.94'/></linearGradient></defs><rect width='1080' height='1920' fill='url(#wodHook)'/><rect x='0' y='1290' width='1080' height='8' fill='${accent}'/><rect x='56' y='56' width='968' height='1808' rx='28' fill='none' stroke='${accentAlpha(0.28)}' stroke-width='1.5'/></svg>`,
      },
      {
        type: 'TEXT', x: 90, y: 120, anchor: 'top-left', track: 2,
        enterBegin: 0.2, enterEnd: 0.65, enterAnimation: 'smoothright', exitEnd: HOOK_D,
        style: { fontFamily: font, color: accent },
        html: `<div style='display:inline-block; background:${accent}; color:${bg}; padding:12px 26px; font-size:24px; font-weight:800; letter-spacing:5px;'>${escapeHtml(gymName)}</div>`,
      },
      {
        type: 'TEXT', x: 90, y: 1360, width: 900, anchor: 'top-left', track: 3,
        enterBegin: 0.5, enterEnd: 1.05, enterAnimation: 'smoothup', exitEnd: HOOK_D,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: `<div style='color:${accent}; font-size:26px; font-weight:800; letter-spacing:7px;'>WORKOUT OF THE DAY</div>` +
          `<div style='margin-top:14px; color:#FFFFFF; font-size:${titleSize}px; line-height:0.92; font-weight:900; letter-spacing:-3px; text-transform:uppercase;'>${escapeHtml(workoutName)}</div>` +
          (focus ? `<div style='margin-top:22px; color:#B7BDC4; font-size:32px; line-height:1.3; font-weight:600;'>${escapeHtml(focus)}</div>` : '') +
          `<div style='margin-top:18px; color:rgba(255,255,255,0.5); font-size:24px; font-weight:700; letter-spacing:4px; text-transform:uppercase;'>${escapeHtml(dateLabel)}${handle ? ' &#183; ' + escapeHtml(handle) : ''}</div>`,
      },
    ],
  };

  // ---- scene 2: the board -------------------------------------------------
  const n = exercises.length;
  const rowStep = 186;
  const cardY = 470;
  const cardH = 70 + n * rowStep + 10;
  const cardBottom = cardY + cardH;

  const rows = exercises.map((ex, i) => ({
    type: 'TEXT', x: 140, y: cardY + 70 + i * rowStep, width: 800, anchor: 'top-left', track: 3 + i,
    enterBegin: round(0.25 + i * 0.14), enterEnd: round(0.65 + i * 0.14),
    enterAnimation: 'smoothright', exitEnd: BOARD_D,
    style: { fontFamily: font, color: '#FFFFFF' },
    html: `<div style='display:flex; gap:30px; align-items:flex-start;'>` +
      `<div style='width:56px; flex:none; color:rgba(255,255,255,0.38); font-size:30px; font-weight:800; padding-top:6px;'>0${i + 1}</div>` +
      `<div style='flex:1;'><div style='color:#FFFFFF; font-size:${nameSize}px; line-height:1.1; font-weight:800; text-transform:uppercase; letter-spacing:-1px;'>${escapeHtml(ex.name)}</div>` +
      (ex.reps ? `<div style='margin-top:8px; color:${accent}; font-size:30px; font-weight:800; letter-spacing:1px; text-transform:uppercase;'>${escapeHtml(ex.reps)}</div>` : '') +
      `</div></div>`,
  }));

  const board = {
    id: 'board',
    duration: BOARD_D,
    backgroundColor: bg,
    transition: 'smoothup',
    transitionId: 'coach',
    transitionDuration: 0.5,
    visuals: [
      {
        type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: BOARD_D,
        svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='wodItem' cx='0.5' cy='0.32' r='0.95'><stop offset='0' stop-color='#12160D'/><stop offset='1' stop-color='${bg}'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#wodItem)'/><path d='M90 415 H990' stroke='rgba(255,255,255,0.14)' stroke-width='2'/><rect x='80' y='${cardY}' width='920' height='${cardH}' rx='36' fill='${accentAlpha(0.05)}' stroke='${accentAlpha(0.4)}' stroke-width='1.5'/><rect x='80' y='${cardY}' width='920' height='10' rx='5' fill='${accent}'/></svg>`,
      },
      {
        type: 'TEXT', x: 90, y: 210, anchor: 'top-left', track: 1, enterBegin: 0, exitEnd: BOARD_D,
        style: { fontFamily: font, color: DIM },
        html: `<div style='color:${DIM}; font-size:24px; font-weight:800; letter-spacing:6px; text-transform:uppercase;'>${escapeHtml(gymName)} &#183; WOD</div>`,
      },
      {
        type: 'TEXT', x: 90, y: 268, width: 900, anchor: 'top-left', track: 2,
        enterBegin: 0.15, enterEnd: 0.55, enterAnimation: 'smoothright', exitEnd: BOARD_D,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: `<div style='color:#FFFFFF; font-size:${boardTitleSize}px; line-height:1; font-weight:900; letter-spacing:-1px; text-transform:uppercase;'>${escapeHtml(workoutName)}</div>` +
          (dateLabel ? `<div style='margin-top:12px; color:${accent}; font-size:26px; font-weight:800; letter-spacing:4px;'>${escapeHtml(dateLabel)}</div>` : ''),
      },
      ...rows,
      {
        type: 'TEXT', x: 540, y: cardBottom + 90, anchor: 'top-center', track: 3 + n,
        enterBegin: round(0.45 + n * 0.14), enterEnd: round(0.85 + n * 0.14), enterAnimation: 'fade', exitEnd: BOARD_D,
        style: { fontFamily: font, color: FOOT },
        html: `<div style='text-align:center; color:${FOOT}; font-size:26px; font-weight:700; letter-spacing:3px;'>${escapeHtml(handle || gymName)}</div>`,
      },
    ],
  };

  // ---- scene 3: coach's note ---------------------------------------------
  const coach = {
    id: 'coach',
    duration: COACH_D,
    backgroundColor: bg,
    visuals: [
      {
        type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: COACH_D,
        svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='wodEnd' cx='0.5' cy='0.36' r='0.95'><stop offset='0' stop-color='#141A0C'/><stop offset='1' stop-color='${bg}'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#wodEnd)'/><circle cx='540' cy='900' r='430' fill='none' stroke='${accentAlpha(0.12)}' stroke-width='2'/><rect x='56' y='56' width='968' height='1808' rx='28' fill='none' stroke='${accentAlpha(0.25)}' stroke-width='1.5'/></svg>`,
      },
      {
        type: 'TEXT', x: 540, y: 500, width: 600, anchor: 'top-center', track: 1,
        enterBegin: 0.2, enterEnd: 0.7, enterAnimation: 'circleopen', exitEnd: COACH_D,
        style: { fontFamily: font, color: accent },
        html: `<div style='text-align:center; color:${accent}; font-size:130px; line-height:0.6; font-weight:900;'>&#8220;</div>` +
          `<div style='margin-top:24px; text-align:center; color:${accent}; font-size:26px; font-weight:800; letter-spacing:6px;'>COACH'S NOTE</div>`,
      },
      {
        type: 'TEXT', x: 540, y: 880, width: 880, anchor: 'center-center', track: 2,
        enterBegin: 0.45, enterEnd: 0.95, enterAnimation: 'smoothup', exitEnd: COACH_D,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: `<div style='text-align:center; color:#FFFFFF; font-size:${noteSize}px; line-height:1.18; font-weight:800;'>${escapeHtml(coachNote)}</div>`,
      },
      {
        type: 'TEXT', x: 540, y: 1230, anchor: 'top-center', track: 3,
        enterBegin: 0.85, enterEnd: 1.25, enterAnimation: 'smoothup', exitEnd: COACH_D,
        style: { fontFamily: font, color: accent },
        html: `<div style='display:inline-block; background:${accent}; color:${bg}; border-radius:999px; padding:24px 58px; font-size:34px; font-weight:900; letter-spacing:1px;'>${escapeHtml(handle || gymName)}</div>`,
      },
      {
        type: 'TEXT', x: 540, y: 1700, anchor: 'top-center', track: 4,
        enterBegin: 1.15, enterEnd: 1.55, enterAnimation: 'fade', exitEnd: COACH_D,
        style: { fontFamily: font, color: FOOT },
        html: `<div style='text-align:center; color:${FOOT}; font-size:24px; font-weight:700; letter-spacing:5px; text-transform:uppercase;'>${escapeHtml(gymName)} &#183; WORKOUT OF THE DAY</div>`,
      },
    ],
  };

  const payload = {
    name: `workout-of-the-day-${workoutName}`.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'workout-of-the-day',
    resolution: config.resolution || 'instagram-reel',
    frameRate: Number(config.frameRate) || 30,
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes: [hook, board, coach],
    // NOTE: no `track` on audios — the live API rejects audios[].track today;
    // with a single bed the array order is all the mixer needs.
    ...(config.musicUrl ? { audios: [{ src: config.musicUrl, volume: Number(config.musicVolume ?? 0.18) }] } : {}),
  };

  // Ready-to-paste caption for the socials tail.
  const caption = [
    `${workoutName}${focus ? ' — ' + focus : ''}`,
    dateLabel,
    '',
    ...exercises.map((e, i) => `${i + 1}. ${e.name}${e.reps ? ' — ' + e.reps : ''}`),
    '',
    `Coach's note: ${coachNote}`,
    '',
    `${handle ? handle + ' ' : ''}#wod #workoutoftheday #training`,
  ].join('\n');

  const meta = {
    workoutName,
    focus,
    dateLabel,
    exerciseCount: exercises.length,
    durationSeconds: round(HOOK_D + BOARD_D + COACH_D - 0.55 - 0.5),
    caption,
  };

  return { payload, meta };
}

const { payload, meta } = buildProject(cfg, data);
return [{ json: { payload, meta: { ...meta, dateIso: data.dateIso, usedFallback: data.usedFallback === true } } }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => `  - ${d.field}: ${d.message}`).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error(`Zvid rejected the project (HTTP ${status}): ${body.message || body.error}\n${details}`);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error(`Render did not finish within ${cfg.timeoutMinutes} minutes (job ${job.id}, state ${job.state}).`);
}

return $input.all();

// Final report — plain JSON, so anything downstream can read every field.
// The MP4 itself is fetched by the `▶ Watch video` node right after this one
// (binary `data`): attach a platform node (Instagram, TikTok, Drive, email...)
// there and pull the text with $('Run summary').first().json.caption.
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : job.result && job.result.url;

return [{
  json: {
    workout: build.meta.workoutName,
    date: build.meta.dateLabel,
    dateIso: build.meta.dateIso,
    usedFallback: build.meta.usedFallback,
    exercises: build.meta.exerciseCount,
    videoSeconds: build.meta.durationSeconds,
    creditsCharged: build.creditsRequired,
    videoUrl: url,
    jobId: job.id,
    caption: build.meta.caption,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// draft, then set dryRun to false in Config to go live.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = `${String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '')}/?project=${project.id}`;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    workout: d.meta.workoutName,
    date: d.meta.dateLabel,
    dateIso: d.meta.dateIso,
    usedFallback: d.meta.usedFallback,
    exercises: d.meta.exerciseCount,
    videoSeconds: d.meta.durationSeconds,
    creditsRequired: d.creditsRequired,
    warnings: d.warnings,
    editorLink,
    draftId,
    caption: d.meta.caption,
    nextStep: editorLink
      ? 'Open editorLink to preview and tweak the draft. Set dryRun to false in Config to render.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];
